function SQ_PUB(jv){try{return String(jv.get('sqPubUrl')||'')}catch(e){return ''}}
function SQ_SET(jv,k,v){try{jv.put(k,String(v))}catch(e){}}
function SQ_GET(jv,k){try{return String(jv.get(k)||'')}catch(e){return ''}}
function SQ_HOSTS(){return ['https://www.shuqi.com','https://shuqi.com','https://c1.shuqireader.com','https://c2.shuqireader.com']}
function SQ_KEY(h){return 'sqsp_'+String(h).replace(/[^a-z0-9]/gi,'').slice(0,24)}
function SQ_AJAX(jv,u,ms){var o={timeout:ms||8000,headers:{'User-Agent':'okhttp/3.12.13'}};
 return String(jv.ajax(u+','+JSON.stringify(o)));}
function SQ_PARSE(h){
 var out=[],re=/href=["'](https?:\/\/[a-z0-9.-]*shuqi[a-z0-9.-]*)["']/gi,m,seen={};
 while((m=re.exec(h))!==null){var u=m[1].replace(/\/$/,'');if(!seen[u]){seen[u]=1;out.push(u)}}
 return out;}
function SQ_uiHelp(jv){SQ_T(jv,'ℹ️ 书旗小说书源：上游为书旗官方 App 加密接口（游客态），无需账号登录。\n搜索/详情/目录/正文/发现均可用；VIP 章正文来自免签 CDN 缓存。');}
function SQ_uiAbout(jv){SQ_T(jv,'ℹ️ UA 固定 okhttp/3.12.13（站点对浏览器 UA 返回 403 拦截页）。\n已内置搜索最小间隔 3 秒与 concurrentRate 限速，请勿连续高频搜索以免触发风控。\n兼容 LegadoTeam 官方版与 legado-E。');}
function SQ_uiCheck(jv){
 SQ_T(jv,'⏳ 正在检查登录状态与接口连通性…');
 try{
  var o={timeout:10000,headers:{'User-Agent':'okhttp/3.12.13','content-type':'application/x-www-form-urlencoded'}};
  var h=SQ_AJAX(jv,'https://www.shuqi.com/ranklist?rank=boyClick',10000);
  if(h.length>5000&&h.indexOf('访问被拒绝')<0){
   SQ_T(jv,'✅ 游客态可用，无需登录（H5 榜单连通，'+h.length+' 字节）\n书源接口正常，可直接搜索阅读。');return;}
  SQ_T(jv,'⚠️ H5 站点返回异常（可能被限频），但加密接口仍可尝试；如搜索失败请稍后重试。');
 }catch(e){SQ_T(jv,'❌ 检查失败：'+String(e).slice(0,120)+'\n请检查网络或点「测试延时」切换线路。');}
}
function SQ_uiFetchPub(jv){
 var pub=SQ_PUB(jv);if(!pub){SQ_T(jv,'⚠️ 请先在上方「网址发布页」输入框填写网址');return;}
 SQ_T(jv,'⏳ 正在从发布页获取网址路线：'+pub);
 try{
  var h=SQ_AJAX(jv,pub,10000);
  var ls=SQ_PARSE(h);
  if(!ls.length){SQ_T(jv,'ℹ️ 书旗为官方固定域名，无独立网址发布页；未从该页解析到线路。\n已保留内置 4 条官方线路，可直接点「测试延时」后切换。');return;}
  SQ_SET(jv,'sqPubLines',ls.join('\n'));
  SQ_T(jv,'✅ 发布页解析完成，共 '+ls.length+' 条线路：\n'+ls.slice(0,8).join('\n')+'\n（书源规则仍使用官方接口域名，线路仅用于 H5 榜单/目录）');
 }catch(e){SQ_T(jv,'❌ 发布页获取失败：'+String(e).slice(0,120)+'\n内置线路仍可用。');}
}
function SQ_uiSpeed(jv){
 SQ_T(jv,'⏳ 开始逐站测速（2 条 H5 + 2 条 CDN，约 5~30 秒），请稍候…');
 var hs=SQ_HOSTS(),msg='📊 测速结果：',best='',bm=99999999,i;
 for(i=0;i<hs.length;i++){
  var h=hs[i],isCdn=h.indexOf('c1.')>=0||h.indexOf('c2.')>=0;
  var probe=isCdn?h+'/httpserver/filecache/get_book_content_34078_2180322_3111111111_0_0.html'
                 :h+'/ranklist?rank=boyClick';
  var t0=Date.now(),st='超时/不支持',ok=false,ms=0;
  try{var r=SQ_AJAX(jv,probe,8000);ms=Date.now()-t0;
   ok=isCdn?(r.indexOf('success_jsonpCallback')>=0&&r.indexOf('\\u3000')>=0)
           :(r.length>5000&&r.indexOf('ranklist-ul')>=0&&r.indexOf('访问被拒绝')<0);
   st=ok?ms+'ms':'内容异常/不支持';}catch(e){ms=Date.now()-t0;st='失败';}
  SQ_SET(jv,SQ_KEY(h),st);
  msg+='\n'+(i+1)+'. ['+(isCdn?'CDN':'H5')+'] '+h.split('//')[1]+' → '+st;
  if(ok&&!isCdn&&ms<bm){bm=ms;best=h;}
 }
 if(best){SQ_SET(jv,SQ_KEY(best),'⚡'+bm+'ms');SQ_SET(jv,'sqWeb',best);
  msg+='\n—— 最快 H5：'+best.split('//')[1]+' ('+bm+'ms)，已自动切换';}
 else msg+='\n—— 无可用 H5 线路，保持原线路（加密接口搜索不受影响）';
 SQ_T(jv,msg);
 try{jv.reLoginView();}catch(e){try{jv.reUiView();}catch(e2){}}
}
function SQ_uiSetLine(jv,host){
 var isCdn=host.indexOf('c1.')>=0||host.indexOf('c2.')>=0;
 SQ_T(jv,'⏳ 正在切换'+(isCdn?' CDN 正文':' H5 站点')+'线路：'+host+' …');
 SQ_SET(jv,isCdn?'sqCdn':'sqWeb',host);
 var probe=isCdn?host+'/httpserver/filecache/get_book_content_34078_2180322_3111111111_0_0.html'
                :host+'/ranklist?rank=boyClick';
 var t0=Date.now(),ok=false,ms=0;
 try{var r=SQ_AJAX(jv,probe,8000);ms=Date.now()-t0;
  ok=isCdn?(r.indexOf('success_jsonpCallback')>=0&&r.indexOf('\\u3000')>=0)
          :(r.length>5000&&r.indexOf('ranklist-ul')>=0&&r.indexOf('访问被拒绝')<0);}catch(e){}
 SQ_SET(jv,SQ_KEY(host),ok?ms+'ms':'不可用');
 SQ_T(jv,ok?('✅ 已切换'+(isCdn?' CDN 正文':' H5 站点')+'：'+host+'（'+ms+'ms）\n'+(isCdn?'章节正文将优先走该 CDN；':'发现页/目录/详情将走该域；')+'加密接口不受影响。')
           :('⚠️ 已写入：'+host+'\n但该线路当前不可达，可点「测试延时」重新选线，或切回主站。'));
 try{jv.reLoginView();}catch(e){try{jv.reUiView();}catch(e2){}}
}
function SQ_uiShowWeb(jv){SQ_T(jv,'🌐 当前 H5 线路：'+SQ_GET(jv,'sqWeb')+'\n📦 当前 CDN 线路：'+SQ_GET(jv,'sqCdn'));}
function SQ_uiSetWeb(jv,host){SQ_uiSetLine(jv,host);}
function SQ_uiResetDev(jv){
 SQ_T(jv,'⏳ 正在重置设备身份…');
 try{jv.put('sqDev','');SQ_T(jv,'✅ 设备身份已重置，下次请求将生成新游客设备（可解决偶发接口异常）。');}
 catch(e){SQ_T(jv,'❌ 重置失败：'+String(e).slice(0,100));}
}
function SQ_uiTokens(jv){return SQ_GET(jv,'sqPubLines');}
function login(){return 'ok';}

